// Feature product photos first, retaining every accessible publication in the gallery.
const order=[10,4,6,8,9,11,5,7,0,1,2,3,...Array.from({length:24},(_,i)=>i+12)];
let shown=0;const gallery=document.getElementById('gallery');const modal=document.getElementById('photo-modal');let lastPhoto;
function showPhotos(){const next=Math.min(shown+12,order.length);for(let i=shown;i<next;i++){const post=posts[order[i]];const b=document.createElement('button');b.type='button';b.setAttribute('aria-label',`Ampliar foto: ${post[2]}`);b.innerHTML=`<img src="assets/${post[0]}.jpg" loading="lazy" alt="${post[2]}"><span aria-hidden="true">↗</span>`;b.addEventListener('click',()=>{lastPhoto=b;document.getElementById('modal-image').src=`assets/${post[0]}.jpg`;document.getElementById('modal-image').alt=post[2];document.getElementById('modal-post').href=post[1].startsWith('https:')?post[1]:`https://www.instagram.com/dolcevitabyvalentina/${post[1]}/`;modal.showModal();document.body.classList.add('modal-open')});gallery.append(b)}shown=next;document.getElementById('gallery-count').textContent=`${shown} de ${posts.length} publicações disponíveis nesta galeria`;document.getElementById('more-photos').hidden=shown===posts.length;}
document.getElementById('more-photos').addEventListener('click',showPhotos);showPhotos();
function closePhoto(){modal.close()}document.getElementById('close-photo').addEventListener('click',closePhoto);modal.addEventListener('click',event=>{if(event.target===modal){const rect=modal.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closePhoto()}});modal.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastPhoto?.focus()});
const stories=[['1b9ba9ccd0f533e4','18397405645083589','Cardápio'],['c5181926fbe8d968','17989035977808739','Suprema'],['59facad835c168ac','17931298628746245','Bastidores'],['1bf11a70c74d1d40','17985952384823116','Clientes'],['08d390e7db46efad','17892342483518257','Lembrancinhas']];document.getElementById('stories').innerHTML=stories.map(s=>`<a class="story-link" href="https://www.instagram.com/stories/highlights/${s[1]}/" target="_blank" rel="noopener noreferrer"><img src="assets/${s[0]}.jpg" alt="Destaque ${s[2]} no Instagram" loading="lazy"><span>${s[2]}</span></a>`).join('');
const toggle=document.getElementById('contact-toggle'),panel=document.getElementById('contact-panel');function closeContact(){panel.hidden=true;toggle.setAttribute('aria-expanded','false')}toggle.addEventListener('click',()=>{const open=panel.hidden;panel.hidden=!open;toggle.setAttribute('aria-expanded',String(open))});document.addEventListener('click',e=>{if(!e.target.closest('.floating-contact'))closeContact()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){closeContact();toggle.focus()}});
